/* 학습 해설
 * Bitmap 구분자·Forward Reverse와 Newline 종료
 * 공백과 comma를 건너뛰는 방향별 탐색이 목록과 hex 입력 해석에 어떻게 쓰이는 지 배웁니다.
 * End_of_str은 NUL 또는 newline, __end_of_region은 isspace 또는 comma입니다. End_of_region은 둘을 합칩니다. Forward finder는 공백·comma를 건너뛰고 종료 문자이면 NULL을 반환합니다. Reverse finder는 start<=end인 동안 끝의 공백·comma를 뒤로 건너뜁니다. 상위 hex parser는 먼저 첫 newline 이전까지만 reverse 탐색 범위로 정합니다.
 * 문자 분류와 입력 경계는 실제 호출 경로를 따라 봅니다. List의 leading region finder에서 newline은 whitespace로 먼저 소비될 수 있지만 숫자 뒤 문법 위치의 newline은 종료 문자입니다. 모든 newline이 항상 같은 단계에서 멈춘다고 단순화하지 않습니다.
 */
static const char *bitmap_find_region(const char *str)
{
	while (__end_of_region(*str))
		str++;

	return end_of_str(*str) ? NULL : str;
}

static const char *bitmap_find_region_reverse(const char *start, const char *end)
{
	while (start <= end && __end_of_region(*end))
		end--;

	return end;
}

static const char *bitmap_parse_region(const char *str, struct region *r)
{
	unsigned int lastbit = r->nbits - 1;

	if (!strncasecmp(str, "all", 3)) {
		r->start = 0;
		r->end = lastbit;
		str += 3;

		goto check_pattern;

/* 학습 해설
 * Bitmap List 문법·All Range와 반복 Pattern
 * 단일 위치·범위·전체 집합·반복 선택을 한 상태 흐름으로 해석하는 원리를 배웁니다.
 * Parser는 대소문자 무관한 all의 앞 3문자를 인식하거나 decimal/N start를 읽습니다. 단일 위치면 end=start, 범위면 hyphen 뒤 end입니다. Pattern이 없으면 off와 group_len을 end+1로 놓아 한 번에 범위를 채웁니다. Colon 패턴은 off/group_len 순으로 숫자를 읽고 slash를 요구합니다. 숫자를 읽은 뒤 separator와 남은 문법의 확인 위치를 따라야 합니다.
 * 문법 start-end:used/group에 맞춰 입력합니다. All도 반복 pattern을 붙일 수 있습니다. All 뒤 임의 접미사를 자동 무시하는 표현이 아닙니다. 이 함수는 오류 포인터·다음 위치·종료 NULL을 반환하며 실제 범위 적용은 상위 함수가 합니다.
 */
static const char *bitmap_parse_region(const char *str, struct region *r)
{
	unsigned int lastbit = r->nbits - 1;

	if (!strncasecmp(str, "all", 3)) {
		r->start = 0;
		r->end = lastbit;
		str += 3;

		goto check_pattern;
	}

	str = bitmap_getnum(str, &r->start, lastbit);
	if (IS_ERR(str))
		return str;

	if (end_of_region(*str))
		goto no_end;

	if (*str != '-')
		return ERR_PTR(-EINVAL);

	str = bitmap_getnum(str + 1, &r->end, lastbit);
	if (IS_ERR(str))
		return str;

/* 학습 해설
 * Bitmap List 적용·실패 뒤 부분 결과
 * 입력 전체를 먼저 검증하지 않는 순차 parser의 상태 변경과 오류 처리 방법을 배웁니다.
 * Bitmap_parselist는 시작할 때 목적 유효 bit를 zero합니다. 각 region에 대해 finder→parse_region→check_region→set_region을 반복합니다. 앞의 정상 region은 즉시 적용되고 뒤 region이 실패해도 그 변경을 rollback하지 않습니다. 따라서 성공 0만 전체 입력을 유효한 결과로 판단할 수 있습니다.
 * 기존 설정을 실패 시 유지하려면 caller가 별도 임시 bitmap에 parse하고 성공 후 교체합니다. 같은 목적 배열에 직접 parse한 뒤 오류만 무시하면 일부 입력이 반영된 상태를 사용하게 됩니다. 성공 결과도 공유 객체에 공개할 때 별도 동기화를 사용합니다.
 */
int bitmap_parselist(const char *buf, unsigned long *maskp, int nmaskbits)
{
	struct region r;
	long ret;

	r.nbits = nmaskbits;
	bitmap_zero(maskp, r.nbits);

	while (buf) {
		buf = bitmap_find_region(buf);
		if (buf == NULL)
			return 0;

		buf = bitmap_parse_region(buf, &r);
		if (IS_ERR(buf))
			return PTR_ERR(buf);

		ret = bitmap_check_region(&r);
		if (ret)
			return ret;

		bitmap_set_region(&r, maskp);
	}

	return 0;
}

/* 학습 해설
 * Bitmap Hex Chunk·역방향 Nibble과32bit 폭
 * Hex 문자열의 오른쪽 자리부터 4bit씩 누적하여 32bit 숫자 하나를 만드는 원리를 배웁니다.
 * Helper는 end의 hex digit을 hex_to_bin으로 변환하여 ret의 i 위치에 OR하고 i를 4씩 늘립니다. Start에 닿거나 separator면 해당 숫자를 완료합니다. 최대 8digit 뒤에도 추가 hex digit이 있으면 EOVERFLOW입니다. 잘못된 digit은 EINVAL입니다. 성공한 chunk만 *num에 저장하고 다음 reverse 위치를 반환합니다.
 * Comma/공백으로 구분된 각 chunk는 32bit 폭입니다. 값을 작게 만드는 leading zero가 있어도 9digit chunk는 허용되지 않습니다. 0x prefix는 이 helper의 문법이 아닙니다. 마지막 성공 저장과 오류 전의 지역 ret를 구분합니다.
 */
static const char *bitmap_get_x32_reverse(const char *start,
					const char *end, u32 *num)
{
	u32 ret = 0;
	int c, i;

	for (i = 0; i < 32; i += 4) {
		c = hex_to_bin(*end--);
		if (c < 0)
			return ERR_PTR(-EINVAL);

		ret |= c << i;

		if (start > end || __end_of_region(*end))
			goto out;
	}

	if (hex_to_bin(*end--) >= 0)
		return ERR_PTR(-EOVERFLOW);
out:
	*num = ret;
	return end;
}

/**
 * bitmap_parse - convert an ASCII hex string into a bitmap.
 * @start: pointer to buffer containing string.
 * @buflen: buffer size in bytes.  If string is smaller than this
 *    then it must be terminated with a \0 or \n. In that case,
 *    UINT_MAX may be provided instead of string length.
 * @maskp: pointer to bitmap array that will contain result.
 * @nmaskbits: size of bitmap, in bits.
 *
 * Commas group hex digits into chunks.  Each chunk defines exactly 32
 * bits of the resultant bitmask.  No chunk may specify a value larger
 * than 32 bits (%-EOVERFLOW), and if a chunk specifies a smaller value
 * then leading 0-bits are prepended.  %-EINVAL is returned for illegal
 * characters. Grouping such as "1,,5", ",44", "," or "" is allowed.
 * Leading, embedded and trailing whitespace accepted.
 */

/* 학습 해설
 * Bitmap Hex Parser·낮은 Chunk와 Endian 배치
 * 사람이 읽는 높은 자리 우선 문자열을 native bitmap의 낮은 위치부터 저장하는 알고리즘을 배웁니다.
 * Bitmap_parse는 buflen 또는 첫 NUL/newline까지의 끝을 정하고 오른쪽 chunk부터 읽습니다. 오른쪽은 bit0..31,그 왼쪽은 bit32..63입니다. 목적을 u32 배열로 보고 일반 경로는 chunk index에 저장합니다. CONFIG_64BIT와 big-endian이 함께 선택되면 chunk^1을 사용해 unsigned long 안의 낮은 32bit 수치 위치에 맞춥니다.
 * Nmaskbits에 맞는 unsigned long 저장 공간을 제공하고 32bit chunk 단위 문법을 사용합니다. 이 입력은 arbitrary wire byte 배열이 아니라 hex 숫자 문자열입니다. Big-endian 경로를 little-endian host에서 CONFIG 이름만 바꿔 동일하게 실행 검증했다고 주장하지 않습니다.
 */
int bitmap_parse(const char *start, unsigned int buflen,
		unsigned long *maskp, int nmaskbits)
{
	const char *end = strnchrnul(start, buflen, '\n') - 1;
	int chunks = BITS_TO_U32(nmaskbits);
	u32 *bitmap = (u32 *)maskp;
	int unset_bit;
	int chunk;

	for (chunk = 0; ; chunk++) {
		end = bitmap_find_region_reverse(start, end);
		if (start > end)
			break;

		if (!chunks--)
			return -EOVERFLOW;

#if defined(CONFIG_64BIT) && defined(__BIG_ENDIAN)
		end = bitmap_get_x32_reverse(start, end, &bitmap[chunk ^ 1]);
#else
		end = bitmap_get_x32_reverse(start, end, &bitmap[chunk]);
#endif
		if (IS_ERR(end))
			return PTR_ERR(end);
	}

/* 학습 해설
 * Bitmap Hex 완료 검사·미사용 Chunk와 부분 오류
 * Hex 입력의 32bit 경계와 마지막 부분 word에서 초과 bit를 검출하는 방법을 배웁니다.
 * 입력 chunk가 목적 BITS_TO_U32 개수를 넘으면 EOVERFLOW입니다. 읽은 chunk보다 목적이 더 크면 unset_bit부터 nmaskbits까지 clear합니다. 마지막 부분 32bit까지 읽었다면 nmaskbits 이상에서 set bit를 찾아 하나라도 있으면 EOVERFLOW입니다. 이 parser는 처음에 전체 목적을 zero하지 않으며 실패하면 먼저 저장한 낮은 chunk가 남을 수 있습니다.
 * 오류 결과를 적용하지 않고 필요하면 임시 bitmap에 parse합니다. 유효 영역의 결과와 저장 word의 unused tail을 나눠 봅니다. 성공 시 의미 없는 모든 저장 tail bit가 언제나 zero된다는 계약으로 확대하지 않습니다.
 */
int bitmap_parse(const char *start, unsigned int buflen,
		unsigned long *maskp, int nmaskbits)
{
	const char *end = strnchrnul(start, buflen, '\n') - 1;
	int chunks = BITS_TO_U32(nmaskbits);
	u32 *bitmap = (u32 *)maskp;
	int unset_bit;
	int chunk;

	for (chunk = 0; ; chunk++) {
		end = bitmap_find_region_reverse(start, end);
		if (start > end)
			break;

		if (!chunks--)
			return -EOVERFLOW;

#if defined(CONFIG_64BIT) && defined(__BIG_ENDIAN)
		end = bitmap_get_x32_reverse(start, end, &bitmap[chunk ^ 1]);
#else
		end = bitmap_get_x32_reverse(start, end, &bitmap[chunk]);
#endif
		if (IS_ERR(end))
			return PTR_ERR(end);
	}

/* 학습 해설
 * CPU Mask Wrap·한 바퀴 순회와 시작점
 * CPU 번호 집합을 특정 위치부터 순회하고 끝에서 돌아와 중복 없이 종료하는 원리를 배웁니다.
 * Cpumask_next_wrap은 n 다음 set CPU를 찾습니다. 끝을 넘으면 wrap=true로 바꾸고 n=-1에서 다시 찾습니다. 이미 wrap한 상태에서 n<start이고 다음 후보가 start 이상이면 nr_cpumask_bits를 반환해 종료합니다. 시작 CPU가 mask에 없어도 돌아온 탐색이 시작 경계를 넘는 조건으로 한 바퀴를 끝낼 수 있습니다.
 * 이 helper를 사용할 때 start,n,wrap의 반복 규약을 맞춥니다. 현재 header의 for_each_cpu_wrap은 별도의 find_next_bit_wrap/__for_each_wrap 경로이므로 이 lib 함수와 같은 실행 경로로 세지 않습니다. 반환 CPU가 nr_cpu_ids 미만인지 확인합니다. Mask가 비어 있는 경우와 시작 bit가 없는 경우를 다루며 순회 중 mask 변경의 동기화는 caller 문맥을 확인합니다.
 */
unsigned int cpumask_next_wrap(int n, const struct cpumask *mask, int start, bool wrap)
{
	unsigned int next;

again:
	next = cpumask_next(n, mask);

	if (wrap && n < start && next >= start) {
		return nr_cpumask_bits;

	} else if (next >= nr_cpumask_bits) {
		wrap = true;
		n = -1;
		goto again;
	}

	return next;
}
EXPORT_SYMBOL(cpumask_next_wrap);

/* These are not inline because of header tangles. */
#ifdef CONFIG_CPUMASK_OFFSTACK
/**
 * alloc_cpumask_var_node - allocate a struct cpumask on a given node
 * @mask: pointer to cpumask_var_t where the cpumask is returned
 * @flags: GFP_ flags
 * @node: memory node from which to allocate or %NUMA_NO_NODE
 *
 * Only defined when CONFIG_CPUMASK_OFFSTACK=y, otherwise is
 * a nop returning a constant 1 (in <linux/cpumask.h>).
 *
 * Return: TRUE if memory allocation succeeded, FALSE otherwise.
 *
 * In addition, mask will be NULL if this fails.  Note that gcc is
 * usually smart enough to know that mask can never be NULL if
 * CONFIG_CPUMASK_OFFSTACK=n, so does code elimination in that case
 * too.
 */

/* 학습 해설
 * CPU Mask Offstack·CONFIG에 따른 저장 수명
 * 큰 CPU 집합을 stack 밖에 보관할 때 빌드 설정이 할당 API의 의미를 바꾸는 원리를 배웁니다.
 * CONFIG_CPUMASK_OFFSTACK에서 는 cpumask_size byte를 kmalloc_node로 요청하여 *mask에 저장하고 NULL 여부를 bool로 반환합니다. DEBUG_PER_CPU_MAPS이면 실패 시 로그와 dump_stack을 호출합니다. Free_cpumask_var는 kfree입니다. Offstack이 꺼진 header 구현은 이미 배열 저장공간을 갖는 cpumask_var_t를 사용하여 alloc은 true,free는 no-op입니다.
 * 선택한 CONFIG와 cpumask_var_t 정의를 함께 읽고 실패 bool을 검사합니다. 일반 alloc은 모든 bit를 0으로 만든다는 보장이 없고 zalloc wrapper가 ZERO flag를 추가합니다. Node 요청을 반드시 그 물리 node에 배치된다는 무조건 보장으로 해석하지 않습니다.
 */
bool alloc_cpumask_var_node(cpumask_var_t *mask, gfp_t flags, int node)
{
	*mask = kmalloc_node(cpumask_size(), flags, node);

#ifdef CONFIG_DEBUG_PER_CPU_MAPS
	if (!*mask) {
		printk(KERN_ERR "=> alloc_cpumask_var: failed!\n");
		dump_stack();
	}
#endif

	return *mask != NULL;
}
EXPORT_SYMBOL(alloc_cpumask_var_node);

/**
 * alloc_bootmem_cpumask_var - allocate a struct cpumask from the bootmem arena.
 * @mask: pointer to cpumask_var_t where the cpumask is returned
 *
 * Only defined when CONFIG_CPUMASK_OFFSTACK=y, otherwise is
 * a nop (in <linux/cpumask.h>).
 * Either returns an allocated (zero-filled) cpumask, or causes the
 * system to panic.
 */
void __init alloc_bootmem_cpumask_var(cpumask_var_t *mask)
{

/* 학습 해설
 * CPU Mask Bootmem·초기 할당 실패의 Panic
 * 부팅 초기의 memory 관리 API와 일반 실행 중 allocation의 서로 다른 실패 정책을 배웁니다.
 * Offstack의 alloc_bootmem_cpumask_var는 cpumask_size와 SMP_CACHE_BYTES 정렬로 memblock_alloc을 호출합니다. NULL이면 함수명과 크기를 담아 panic합니다. 원본 문서는 성공 객체를 zero-filled로 설명합니다. Free_bootmem_cpumask_var는 동일 크기를 memblock_free로 반환하며 일반 kfree를 호출하지 않습니다.
 * 초기화 단계와 allocation 출처가 맞는 환경에서 사용합니다. 이 API는 실패 bool을 반환하는 normal alloc의 대체가 아닙니다. Offstack이 꺼진 header에서 는 boot alloc/free도 no-op이므로 빌드 경로를 구분합니다.
 */
void __init alloc_bootmem_cpumask_var(cpumask_var_t *mask)
{
	*mask = memblock_alloc(cpumask_size(), SMP_CACHE_BYTES);
	if (!*mask)
		panic("%s: Failed to allocate %u bytes\n", __func__,
		      cpumask_size());
}

/**
 * free_cpumask_var - frees memory allocated for a struct cpumask.
 * @mask: cpumask to free
 *
 * This is safe on a NULL mask.
 */
void free_cpumask_var(cpumask_var_t mask)
{
	kfree(mask);
}
EXPORT_SYMBOL(free_cpumask_var);

/**
 * free_bootmem_cpumask_var - frees result of alloc_bootmem_cpumask_var
 * @mask: cpumask to free
 */
void __init free_bootmem_cpumask_var(cpumask_var_t mask)
{

/* 학습 해설
 * CPU Local Spread·NUMA 거리와 순번 Modulo
 * CPU를 단순한 번호 순서 대신 node와의 거리 순서로 선택하고 요청 순번을 순환시키는 방법을 배웁니다.
 * I를 num_online_cpus로 modulo한 뒤 cpu_online_mask와 node를 sched_numa_find_nth_cpu에 전달합니다. 그 helper는 NUMA 거리 단계에서 i번째 CPU를 찾고 NUMA_NO_NODE에서 는 online 교집합의 순번을 찾습니다. 반환 CPU가 nr_cpu_ids 이상이면 WARN_ON하지만 wrapper가 다른 CPU로 재시도하는 fallback은 없습니다.
 * Online CPU가 양수이고 선택 중 topology·hotplug가 적절히 보호되는 호출 문맥을 사용합니다. 선택한 번호가 이후에도 online으로 유지된다는 예약을 이 함수만으로 얻지 않습니다. 전체 CPU 열거에는 원본 주석의 NUMA hop iterator 비용을 비교합니다.
 */
unsigned int cpumask_local_spread(unsigned int i, int node)
{
	unsigned int cpu;

	/* Wrap: we always want a cpu. */
	i %= num_online_cpus();

	cpu = sched_numa_find_nth_cpu(cpu_online_mask, i, node);

	WARN_ON(cpu >= nr_cpu_ids);
	return cpu;
}
EXPORT_SYMBOL(cpumask_local_spread);

static DEFINE_PER_CPU(int, distribute_cpu_mask_prev);

/**
 * cpumask_any_and_distribute - Return an arbitrary cpu within src1p & src2p.
 * @src1p: first &cpumask for intersection
 * @src2p: second &cpumask for intersection
 *
 * Iterated calls using the same srcp1 and srcp2 will be distributed within
 * their intersection.
 *
 * Return: >= nr_cpu_ids if the intersection is empty.
 */

/* 학습 해설
 * CPU 교집합 분배·Per CPU 이전 선택
 * 두 조건을 모두 만족하는 CPU를 고르고 호출 CPU별 이전 위치를 기억해 선택을 분산하는 원리를 배웁니다.
 * DEFINE_PER_CPU의 distribute_cpu_mask_prev를 __this_cpu_read로 읽고 prev+1부터 두 mask의 교집합 set bit를 wrap 탐색합니다. Next<nr_cpu_ids인 경우만 이전 선택을 갱신합니다. 초기 prev0에서 첫 탐색은 1부터 시작하므로 가능한 경우 CPU0을 건너뜁니다. 빈 교집합의 종료값은 상태를 갱신하지 않습니다.
 * 두 mask의 공통 후보와 nr_cpu_ids 미만 반환 여부를 확인합니다. Per CPU 저장이므로 전체 시스템의 하나의 round-robin counter가 아닙니다. CPU 이동·선점 및 같은 CPU의 동시 접근 조건은 __this_cpu primitive와 caller 문맥에 맞춰 확인합니다.
 */
unsigned int cpumask_any_and_distribute(const struct cpumask *src1p,
			       const struct cpumask *src2p)
{
	unsigned int next, prev;

	/* NOTE: our first selection will skip 0. */
	prev = __this_cpu_read(distribute_cpu_mask_prev);

	next = find_next_and_bit_wrap(cpumask_bits(src1p), cpumask_bits(src2p),
					nr_cpumask_bits, prev + 1);
	if (next < nr_cpu_ids)
		__this_cpu_write(distribute_cpu_mask_prev, next);

