/* 학습 해설
 * Software Popcount32·병렬 작은 Counter 합치기
 * 한32bit 숫자의1bit 개수를 작은 필드별 합으로 계산하는 SWAR 산술 원리를 배웁니다.
 * W-((w>>1)&0x55555555)는 각2bit 그룹의 set 개수를 만듭니다. 0x33333333 mask와 shift2는 두2bit counter를4bit counter로 합칩니다. Shift4와0x0f0f0f0f는 byte별 개수를 만듭니다. Fast multiplier 분기는0x01010101 곱의 높은 byte에서 전체 합을 얻습니다. 다른 분기는 shift8/16 합과0xff mask로 같은 개수를 구합니다.
 * 입력의 수치 bit 개수를 구할 때 사용하며 숫자 크기·최고 set 위치와 구분합니다. CONFIG_ARCH_HAS_FAST_MULTIPLIER는 선택 산술 구현을 바꿉니다. CPU 고유 popcount instruction과 이 software body의 선택 경로를 함께 확인합니다.
 */
unsigned int __sw_hweight32(unsigned int w)
{
#ifdef CONFIG_ARCH_HAS_FAST_MULTIPLIER
	w -= (w >> 1) & 0x55555555;
	w =  (w & 0x33333333) + ((w >> 2) & 0x33333333);
	w =  (w + (w >> 4)) & 0x0f0f0f0f;
	return (w * 0x01010101) >> 24;
#else
	unsigned int res = w - ((w >> 1) & 0x55555555);
	res = (res & 0x33333333) + ((res >> 2) & 0x33333333);
	res = (res + (res >> 4)) & 0x0F0F0F0F;
	res = res + (res >> 8);
	return (res + (res >> 16)) & 0x000000FF;
#endif
}
EXPORT_SYMBOL(__sw_hweight32);

unsigned int __sw_hweight16(unsigned int w)
{
	unsigned int res = w - ((w >> 1) & 0x5555);
	res = (res & 0x3333) + ((res >> 2) & 0x3333);
	res = (res + (res >> 4)) & 0x0F0F;
	return (res + (res >> 8)) & 0x00FF;
}
EXPORT_SYMBOL(__sw_hweight16);

/* 학습 해설
 * Software Popcount8·16과 낮은 폭의 합
 * 같은 병렬 bit 개수 계산을8bit와16bit에 맞춰 줄이고 mask의 폭을 이해합니다.
 * Hweight16은0x5555로2bit counter,0x3333으로4bit counter,0x0f0f로 byte counter를 구합니다. Shift8 합을0xff로 제한하여 반환합니다. Hweight8은0x55와0x33으로 같은 단계를 거친 뒤 shift4 합을0x0f로 제한합니다. 인자는 unsigned int지만 대상 폭은 각각 낮은16bit와8bit입니다.
 * 필요한 폭에 맞는 API를 선택합니다. 일반32bit 전체의 count가 필요하면8/16 variant로 대체하지 않습니다. Mask가 어느 bit를 유지하고 최종 개수가 어느 폭에 들어가는 지 작은 binary 예제로 검산합니다.
 */
unsigned int __sw_hweight16(unsigned int w)
{
	unsigned int res = w - ((w >> 1) & 0x5555);
	res = (res & 0x3333) + ((res >> 2) & 0x3333);
	res = (res + (res >> 4)) & 0x0F0F;
	return (res + (res >> 8)) & 0x00FF;
}
EXPORT_SYMBOL(__sw_hweight16);

unsigned int __sw_hweight8(unsigned int w)
{
	unsigned int res = w - ((w >> 1) & 0x55);
	res = (res & 0x33) + ((res >> 2) & 0x33);
	return (res + (res >> 4)) & 0x0F;
}
EXPORT_SYMBOL(__sw_hweight8);

unsigned long __sw_hweight64(__u64 w)
{
#if BITS_PER_LONG == 32
	return __sw_hweight32((unsigned int)(w >> 32)) +
	       __sw_hweight32((unsigned int)w);
#elif BITS_PER_LONG == 64
#ifdef CONFIG_ARCH_HAS_FAST_MULTIPLIER
	w -= (w >> 1) & 0x5555555555555555ul;
	w =  (w & 0x3333333333333333ul) + ((w >> 2) & 0x3333333333333333ul);

/* 학습 해설
 * Software Popcount64·Word 폭과 분할 합
 * 64bit 자료를 native word 폭과 곱셈 비용에 맞춰 두 방식으로 세는 원리를 배웁니다.
 * BITS_PER_LONG32 분기는 높은32bit와 낮은32bit를 각각 hweight32로 세어 더합니다. 64 분기는64bit 폭의0x5555/0x3333/0x0f 상수로 byte count를 만듭니다. Fast multiplier이면0x0101010101010101 곱을 shift56하여 합을 얻습니다. 다른 분기는 shift8/16/32로 합친 뒤0xff를 반환합니다.
 * 최대 결과64와 반환 unsigned long의 폭을 구분합니다. 두32bit 반쪽은 겹치지 않아 개수를 더할 수 있습니다. Host64에서 BITS_PER_LONG32 분기를 선택한 시험은 분할 산술 검증이며 native32bit ABI 시험과 다르게 표시합니다.
 */
unsigned long __sw_hweight64(__u64 w)
{
#if BITS_PER_LONG == 32
	return __sw_hweight32((unsigned int)(w >> 32)) +
	       __sw_hweight32((unsigned int)w);
#elif BITS_PER_LONG == 64
#ifdef CONFIG_ARCH_HAS_FAST_MULTIPLIER
	w -= (w >> 1) & 0x5555555555555555ul;
	w =  (w & 0x3333333333333333ul) + ((w >> 2) & 0x3333333333333333ul);
	w =  (w + (w >> 4)) & 0x0f0f0f0f0f0f0f0ful;
	return (w * 0x0101010101010101ul) >> 56;
#else
	__u64 res = w - ((w >> 1) & 0x5555555555555555ul);
	res = (res & 0x3333333333333333ul) + ((res >> 2) & 0x3333333333333333ul);
	res = (res + (res >> 4)) & 0x0F0F0F0F0F0F0F0Ful;
	res = res + (res >> 8);
	res = res + (res >> 16);
	return (res + (res >> 32)) & 0x00000000000000FFul;
#endif
#endif
}
EXPORT_SYMBOL(__sw_hweight64);

/* 학습 해설
 * Llist Batch·CAS 실패와 마지막 Link 갱신
 * 여러 노드를 이미 연결한 묶음을 shared head 앞에 한 번에 공개하는 원리를 배웁니다.
 * 먼저 READ_ONCE로 head의 first를 읽고 new_last->next를 그 first에 연결합니다. Try_cmpxchg는 head가 예상 first와 같으면 new_first를 공개하고 성공합니다. 실패하면 first를 실제 head 값으로 갱신하므로 loop에서 new_last->next도 그 값에 다시 연결합니다. 반환 !first는 성공 직전에 목록이 비어 있었는 지를 뜻합니다.
 * New_first부터 new_last까지 올바르게 연결되고 끝이 실제 마지막인 새 묶음을 제공합니다. 같은 node를 동시에 다른 list에 넣지 않습니다. 반환 false도 삽입 성공이며 기존 목록이 있었다는 뜻입니다. 객체 초기화·수명과 NMI-safe cmpxchg 조건을 유지합니다.
 */
bool llist_add_batch(struct llist_node *new_first, struct llist_node *new_last,
		     struct llist_head *head)
{
	struct llist_node *first = READ_ONCE(head->first);

	do {
		new_last->next = first;
	} while (!try_cmpxchg(&head->first, &first, new_first));

	return !first;
}
EXPORT_SYMBOL_GPL(llist_add_batch);

/**
 * llist_del_first - delete the first entry of lock-less list
 * @head:	the head for your lock-less list
 *
 * If list is empty, return NULL, otherwise, return the first entry
 * deleted, this is the newest added one.
 *
 * Only one llist_del_first user can be used simultaneously with
 * multiple llist_add users without lock.  Because otherwise
 * llist_del_first, llist_add, llist_add (or llist_del_all, llist_add,
 * llist_add) sequence in another user may change @head->first->next,
 * but keep @head->first.  If multiple consumers are needed, please
 * use llist_del_all or use lock between consumers.
 */

/* 학습 해설
 * Llist Del First·Acquire와 단일 소비자
 * 첫 노드를 하나씩 제거하는 CAS loop와 다중 소비자에서 필요한 별도 제약을 배웁니다.
 * Smp_load_acquire로 head를 읽고 NULL이면 종료합니다. Entry->next를 READ_ONCE로 읽어 CAS의 새 head로 전달합니다. 실패하면 entry가 갱신되어 새 next를 읽습니다. 성공하면 원래 첫 entry를 반환합니다. 여러 add와 한 del_first 소비자는 가능하지만 여러 소비자가 del_first 또는 del_all을 섞으면 별도 lock이 필요하다고 원본은 규정합니다.
 * 한 소비자 규약을 지키거나 소비자끼리 잠금으로 직렬화합니다. 반환 node를 사용한 뒤 수명과 재삽입 조건을 관리합니다. CAS가 있다는 이유로 모든 pop 조합에 lock이 없어도 된다고 판단하지 않습니다.
 */
struct llist_node *llist_del_first(struct llist_head *head)
{
	struct llist_node *entry, *next;

	entry = smp_load_acquire(&head->first);
	do {
		if (entry == NULL)
			return NULL;
		next = READ_ONCE(entry->next);
	} while (!try_cmpxchg(&head->first, &entry, next));

	return entry;
}
EXPORT_SYMBOL_GPL(llist_del_first);

/**
 * llist_del_first_this - delete given entry of lock-less list if it is first
 * @head:	the head for your lock-less list
 * @this:	a list entry.
 *
 * If head of the list is given entry, delete and return %true else
 * return %false.
 *
 * Multiple callers can safely call this concurrently with multiple
 * llist_add() callers, providing all the callers offer a different @this.
 */

/* 학습 해설
 * Llist Del This·첫 항목의 신원 검사
 * 특정 node가 첫 항목인 경우에만 제거하는 연산의 조건과 concurrent caller 계약을 배웁니다.
 * Acquire로 entry를 읽고 entry!=this이면 false입니다. 같으면 next를 읽고 head CAS로 제거합니다. CAS가 실패해 실제 head가 바뀌면 entry가 갱신되어 다시 신원 검사합니다. 성공하면 true입니다. 원본은 여러 add와 concurrent 호출이 가능하되 각 caller가 서로 다른 this를 제공하는 조건을 명시합니다.
 * 실제로 존재하고 수명이 보호되는 비 NULL node를 this로 제공합니다. 이 API가 목록 중간의 임의 node를 탐색·제거한다고 생각하지 않습니다. 여러 caller가 같은 node를 제공하는 경우까지 원본의 허용 조건으로 확대하지 않습니다.
 */
bool llist_del_first_this(struct llist_head *head,
			  struct llist_node *this)
{
	struct llist_node *entry, *next;

	/* acquire ensures orderig wrt try_cmpxchg() is llist_del_first() */
	entry = smp_load_acquire(&head->first);
	do {
		if (entry != this)
			return false;
		next = READ_ONCE(entry->next);
	} while (!try_cmpxchg(&head->first, &entry, next));

	return true;
}
EXPORT_SYMBOL_GPL(llist_del_first_this);

/**
 * llist_reverse_order - reverse order of a llist chain
 * @head:	first item of the list to be reversed
 *
 * Reverse the order of a chain of llist entries and return the
 * new first entry.
 */
struct llist_node *llist_reverse_order(struct llist_node *head)
{

/* 학습 해설
 * Llist Reverse·분리한 Chain의 Link 방향
 * 추가 순서의 반대로 쌓인 singly linked chain을 뒤집어 오래된 항목부터 처리하는 원리를 배웁니다.
 * New_head=NULL에서 시작하여 현재 tmp를 잡고 원래 head->next를 다음 head로 저장합니다. Tmp->next를 지금까지 뒤집은 new_head로 바꾸고 new_head=tmp로 이동합니다. 입력이 끝날 때까지 반복한 뒤 새 첫 node를 반환합니다. 원래 다음 link를 먼저 보관해야 남은 chain을 잃지 않습니다.
 * Llist_del_all로 분리하는 등 독점적으로 다루는 유한 NULL 종료 chain에 사용합니다. 공유 head에서 다른 producer가 수정 중인 chain을 임의로 뒤집지 않습니다. 반환값을 새 chain 입구로 사용하며 empty는 NULL입니다.
 */
struct llist_node *llist_reverse_order(struct llist_node *head)
{
	struct llist_node *new_head = NULL;

	while (head) {
		struct llist_node *tmp = head;
		head = head->next;
		tmp->next = new_head;
		new_head = tmp;
	}

	return new_head;
}
EXPORT_SYMBOL_GPL(llist_reverse_order);

/* 학습 해설
 * Llist 초기화·NULL Head와 Self Node Marker
 * 목록의 빈 상태와 node의 비소속 표시를 서로 다른 pointer 값으로 표현하는 방법을 배웁니다.
 * Llist_head는 first, llist_node는 next 한 필드입니다. LLIST_HEAD_INIT와 init_llist_head는 first=NULL로 빈 목록을 만듭니다. Init_llist_node는 next=node로 self marker를 만듭니다. 정상 NULL 종료 chain에 연결된 node의 next는 자신을 가리키지 않으므로 llist_on_list는 next!=node를 검사합니다.
 * Node 소속 marker를 사용할 때 init_llist_node 규약을 지킵니다. Self marker는 실제 chain의 종단 표현이 아니므로 그 상태의 node를 chain 순회 시작으로 넘기지 않습니다. 정적 head 선언과 동적 init의 같은 빈 표현을 확인합니다.
 */
static inline void init_llist_node(struct llist_node *node)
{
	node->next = node;
}

/**
 * llist_on_list - test if a lock-list list node is on a list
 * @node:	the node to test
 *
 * When a node is on a list the ->next pointer will be NULL or
 * some other node.  It can never point to itself.  We use that
 * in init_llist_node() to record that a node is not on any list,
 * and here to test whether it is on any list.
 */
static inline bool llist_on_list(const struct llist_node *node)
{
	return node->next != node;
}

/**
 * llist_entry - get the struct of this entry
 * @ptr:	the &struct llist_node pointer.
 * @type:	the type of the struct this is embedded in.
 * @member:	the name of the llist_node within the struct.
 */
#define llist_entry(ptr, type, member)		\

/* 학습 해설
 * Llist 상태 조회·Empty와 On List의 한계
 * 빠른 pointer 조회가 동시 변경 중 상태 예약이나 객체 수명 보호를 대신하지 않는 다는 점을 배웁니다.
 * Llist_empty는 READ_ONCE(head->first)==NULL을 반환하고 원본은 정확하거나 최신이라는 보장을 하지 않는 다고 설명합니다. Llist_on_list는 next!=node marker를 보고 llist_next는 plain next를 반환합니다. 이 조회 함수들은 node를 제거하거나 새 소유권을 얻지 않습니다.
 * Empty 확인 뒤 다른 CPU가 add할 수 있으므로 필요한 실제 동작의 atomic API 결과를 사용합니다. On_list는 초기화·삭제 후 marker 관리 규약에 달린 표시입니다. Next 조회는 안전하게 분리되거나 보호된 node 수명 안에서 사용합니다.
 */
static inline bool llist_empty(const struct llist_head *head)
{
	return READ_ONCE(head->first) == NULL;
}

static inline struct llist_node *llist_next(struct llist_node *node)
{
	return node->next;
}

extern bool llist_add_batch(struct llist_node *new_first,
			    struct llist_node *new_last,
			    struct llist_head *head);

static inline bool __llist_add_batch(struct llist_node *new_first,
				     struct llist_node *new_last,
				     struct llist_head *head)
{
	new_last->next = head->first;
	head->first = new_first;
	return new_last->next == NULL;
}

/**
 * llist_add - add a new entry
 * @new:	new entry to be added
 * @head:	the head for your lock-less list
 *
 * Returns true if the list was empty prior to adding this entry.
 */

/* 학습 해설
 * Llist 비원자 Add·이중 Underscore 규약
 * 이름이 비슷한 helper라도 CAS가 있는 경로와 plain pointer 대입 경로의 동기화가 다름을 배웁니다.
 * __llist_add_batch는 new_last->next=head->first와 head->first=new_first를 plain 대입하고 이전 next가 NULL인지 반환합니다. __llist_add는 같은 node를 양 끝으로 전달합니다. 일반 llist_add는 llist_add_batch의 CAS 경로에 연결됩니다. Double underscore variant에는 동시 producer retry가 없습니다.
 * 독점 접근이나 별도 보호가 있는 문맥에서 만 plain variant를 사용합니다. 같은 bool 반환이 같은 concurrency 계약을 의미하지 않습니다. 새 묶음의 연결과 유효 수명은 atomic variant와 마찬가지로 caller가 준비합니다.
 */
static inline bool __llist_add_batch(struct llist_node *new_first,
				     struct llist_node *new_last,
				     struct llist_head *head)
{
	new_last->next = head->first;
	head->first = new_first;
	return new_last->next == NULL;
}

/**
 * llist_add - add a new entry
 * @new:	new entry to be added
 * @head:	the head for your lock-less list
 *
 * Returns true if the list was empty prior to adding this entry.
 */
static inline bool llist_add(struct llist_node *new, struct llist_head *head)
{
	return llist_add_batch(new, new, head);
}

static inline bool __llist_add(struct llist_node *new, struct llist_head *head)
{
	return __llist_add_batch(new, new, head);
}

/* 학습 해설
 * Llist Del All·Atomic Detach와 반환 Chain
 * 전체 목록을 한 pointer 교환으로 분리하고 detached chain을 caller가 처리하는 원리를 배웁니다.
 * Llist_del_all은 xchg(&head->first,NULL)로 shared head를 비우면서 이전 first를 반환합니다. 분리 이후 추가되는 node는 새 shared head로 들어가며 이전 chain과 구분됩니다. __llist_del_all은 first를 plain 읽고 NULL을 대입하는 별도 비원자 경로입니다. 분리된 chain의 순서는 최근 삽입이 먼저입니다.
 * 여러 producer와 여러 del_all consumer 조합은 원본의 허용 표를 따릅니다. Del_first consumer와 섞을 때는 별도 lock 조건을 확인합니다. 반환 chain의 처리·해제·재사용 수명은 caller가 관리합니다.
 */
static inline struct llist_node *llist_del_all(struct llist_head *head)
{
	return xchg(&head->first, NULL);
}

static inline struct llist_node *__llist_del_all(struct llist_head *head)
{
	struct llist_node *first = head->first;

	head->first = NULL;
	return first;
}

extern struct llist_node *llist_del_first(struct llist_head *head);

/**
 * llist_del_first_init - delete first entry from lock-list and mark is as being off-list
 * @head:	the head of lock-less list to delete from.
 *
 * This behave the same as llist_del_first() except that llist_init_node() is called
 * on the returned node so that llist_on_list() will report false for the node.
 */
static inline struct llist_node *llist_del_first_init(struct llist_head *head)
{
	struct llist_node *n = llist_del_first(head);

/* 학습 해설
 * Llist Del First Init·제거와 Marker Reset
 * 제거 결과의 pointer와 비소속 marker 갱신을 하나의 wrapper로 연결하는 방법을 배웁니다.
 * Llist_del_first_init은 일반 del_first 결과를 n에저장합니다. N이있으면 init_llist_node(n)로 next를 self로바꾸고 n을 반환합니다. NULL 결과에서 는 초기화를 하지 않습니다. 따라서 on_list 검사는 성공제거 node에 false를 보고하지만일반 del_first의소비자제약은 그대로유지됩니다.
 * 반환 node를 다시삽입할 때새 next가구성된다는 점을 읽습니다. Initwrapper가다중 소비자 ABA 조건이나수명문제를 자동해결한다고설명하지 않습니다. NULL인지검사한후자료 객체로접근합니다.
 */
static inline struct llist_node *llist_del_first_init(struct llist_head *head)
{
	struct llist_node *n = llist_del_first(head);

	if (n)
		init_llist_node(n);
	return n;
}

extern bool llist_del_first_this(struct llist_head *head,
				 struct llist_node *this);

struct llist_node *llist_reverse_order(struct llist_node *head);

#endif /* LLIST_H */

/* 학습 해설
 * Plist 삽입·두 Tier와 양쪽 우선순위 탐색
 * 모든 node의 순서와 서로 다른 우선순위 대표의 순서를 따로 유지하여 삽입 후보를 찾는 원리를 배웁니다.
 * Node_list는 모든 node를 prio 숫자가 작은 순서로 연결하고 같은 prio는 FIFO입니다. Prio_list는 서로 다른 prio의 대표들을 연결한 ring입니다. Plist_add는 앞 iter와 뒤 reverse_iter를 비교하여 새 prio의 삽입 위치를 찾습니다. 새 prio이면 대표 ring에도 연결하고 실제 node는 다음 prio 그룹 앞 또는 전체 tail에 넣습니다.
 * Init한 비소속 node를 넣고 caller가 접근 잠금을 유지합니다. 숫자가 작을 수록 높은 우선순위라는 plist 정책을 사용합니다. Node가 이미 연결되어 있거나 prio를 연결 중 임의 변경한 경우를 올바른 입력으로 취급하지 않습니다.
 */
void plist_add(struct plist_node *node, struct plist_head *head)
{
	struct plist_node *first, *iter, *prev = NULL, *last, *reverse_iter;
	struct list_head *node_next = &head->node_list;

	plist_check_head(head);
	WARN_ON(!plist_node_empty(node));
	WARN_ON(!list_empty(&node->prio_list));

	if (plist_head_empty(head))
